# apply_walkforward_and_run.py — drops 4 files and sweeps ensemble alpha in
# a walk-forward GBM backtest, aiming for matchup log-loss below 0.64.
import base64, sys, pathlib

FILES = {
    'src/features/rolling.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
    'src/eval/backtest_gbm_walkforward.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")

    print(f"\nrunning walk-forward: init train=36, retrain every 10, T recalibrated every 10\n")
    results = {}
    for alpha in [1.0, 0.85, 0.7, 0.55, 0.4]:
        print(f"--- alpha={alpha} ---")
        out = backtest_gbm_walkforward(
            races, entries, sessions, loopstats,
            initial_train_races=36,
            retrain_every_n=10,
            calib_window=25,
            recalibrate_every_n=10,
            ensemble_alpha=alpha,
            n_samples=3000,
        )
        s = summarize_wf(out["metrics"])
        results[alpha] = s
        print(s.round(4).to_string())
        print()

    print("\n=== SUMMARY: ALL-track metrics vs. ensemble alpha ===")
    summary = pd.DataFrame({
        alpha: results[alpha].loc["ALL"][["winner_logloss", "matchup_logloss", "spearman_rho", "top5_accuracy"]]
        for alpha in results
    }).T
    summary.index.name = "alpha"
    print(summary.round(4).to_string())

    best = summary["matchup_logloss"].idxmin()
    print(f"\nBest alpha for matchup LL: {best}  (matchup LL = {summary.loc[best, 'matchup_logloss']:.4f})")

if __name__ == "__main__":
    main()
